1	// Tập 7 · C4 · ĐOẠN D = S16–S20. Hàng chồng theo tuần (đoạn c) tách bốn nhóm thập kỷ; trước mỗi nhóm một chồng điển hình (W2, bó của the stack);
2	// đường lãi 30 năm (accent) chạy qua hàng: lãi tụt mạnh vào 2010s trong khi chồng 2010s cao hơn 1990s (vạch nét đứt) → bốn ngoặc khoảng chênh
3	// (V6, cùng thang cột khoảng chênh của đoạn c) khớp chồng, không khớp đường lãi → 2020s gần ngang the stack của Tessa → về thế giới. Mốc giờ: spine.json.
4	import { setup, figure, gesture, figTag, WeekRow, theStack, stackSet, BUNDLE_TH, modeLook, followLight, chrome, label, seg2, vbrace, dip,
5	  show, pulse, C, ease, lin, mix, THREE } from '/episodes/ep007/world/c4kit.js';
6	import { Ribbon } from '/toolkit/factory/world/lib3d.js';
7	
8	const SEG = '/episodes/ep007/world/c4/d-s16-s20/';
9	const RY = 0.35;
10	
11	export async function boot(res) {
12	  const poses = {
13	    wD0: { pos: [-7.4, 2.9, 10.4], tgt: [1.8, 1.2, -0.8], fov: 46, chart: 0 },
14	    cD: { pos: [2.2, 3.0, 26], tgt: [2.2, 3.0, 0], fov: 20.6, chart: 1 },
15	    wEnd: { pos: [-7.6, 2.6, 7.6], tgt: [-2.4, 1.0, 0], fov: 38, chart: 0 },
16	  };
17	  const { S, D, G, cue, MV, st, O, renderer, scene, floor, key, CAM } = await setup(SEG, res, poses);
18	  const b = cue, X = S.x, N = S.weeks.length, W = X.x1 - X.x0, U = BUNDLE_TH / G.bundle_usd;
19	  const GS = G.stack_total * U / S.spread_now, dec = (i) => (i < S.rng[1][0] ? 0 : i < S.rng[2][0] ? 1 : i < S.rng[3][0] ? 2 : 3);
20	  const hm = figure(scene, { x: X.house }), tstack = theStack(scene, G, { x: X.stack });
21	  stackSet(tstack, G.stack_total);
22	  const row = WeekRow(scene, S.extra, { x0: X.x0, width: W, z: 0.05, depth: 0.22, unit: U });
23	  const xc = (k) => X.x0 + (S.rng[k][0] + S.rng[k][1]) / 2 / N * W, xw = (i) => X.x0 + (i + 0.5) * W / N;
24	  const stacks = [0, 1, 2, 3].map((k) => theStack(scene, G, { x: xc(k) + (k - 1.5) * X.split, z: X.zs }));
25	  stacks.forEach((s, k) => { s.userData.checks = { role: 'bar', series: 'era-median', key: `era-stack-${k}` }; });
26	  const l30 = Ribbon({ color: C.accent, z: 0.6, width: 0.055, maxPts: N }), l10 = Ribbon({ color: '#9CC0FF', z: 0.62, width: 0.11, maxPts: N });
27	  scene.add(l30, l10); l30.userData.checks = { role: 'series', series: 'r30', key: 'rate-30' };
28	  const LAB = [[D('era1991_span'), D('era1991_median_r30'), D('era1991_median_extra_total'), ['era1991_span', 'era1991_median_r30'], 'era1991_median_extra_total', D('era1991_median_spread'), 'era1991_median_spread'],
29	    [D('era2000_name'), D('era2000_median_r30'), D('era2000_median_extra_total'), ['era2000_name', 'era2000_median_r30'], 'era2000_median_extra_total', D('era2000_median_spread'), 'era2000_median_spread'],
30	    [D('era2010_name'), D('era2010_median_r30'), D('era2010_median_extra_total'), ['era2010_name', 'era2010_median_r30'], 'era2010_median_extra_total', D('era2010_median_spread'), 'era2010_median_spread'],
31	    [D('era2020_name'), null, D('era2020_median_extra_total'), ['era2020_name'], 'era2020_median_extra_total', D('era2020_median_spread'), 'era2020_median_spread']];
32	  const tagAt = [b.e1.fifteen, b.e2.fourteen, b.e3.twenty, b.e6.one], brAt = [b.e4.four, b.e4.four + 0.25, b.e4.seven, b.e4.seven + 0.25];
33	  const cW = new THREE.Color(C.warn), cWd = new THREE.Color('#4A3F2A');
34	
35	  function frame(t) {
36	    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
37	    followLight(key, pose.tgt); modeLook(scene, floor, cw); gesture(hm, t, S.gestures);
38	    const sp = ease(t, b.e0.decade - 0.05, b.e0.decade + 0.9), dx = (i) => (dec(i) - 1.5) * X.split * sp;
39	    // nhóm đang nói sáng; S19 cả bốn như nhau; sau S20 về thế giới cả hàng tối nhẹ
40	    const cur = t < S.up[0] ? -1 : t < S.up[1] ? 0 : t < S.up[2] ? 1 : t < b.e4.gap ? 2 : t < S.up[3] ? 9 : 3;
41	    row.set({ grow: 1, dx, color: (i, c) => { const d = dec(i), on = cur === -1 || cur === 9 ? 0.55 : d === cur ? 1 : 0.3; c.copy(cWd).lerp(cW, on); } });
42	    stacks.forEach((s, k) => stackSet(s, S.med[k] * ease(t, S.up[k], S.up[k] + 1.1)));
43	    // đường lãi 30 năm qua hàng (dời theo nhóm); đoạn 2010s loé ở "far" (lãi thấp hẳn) và "lower"
44	    const pts = [], p10 = []; for (let i = 0; i < N; i += 2) { const p = [xw(i) + dx(i), S.r30[i] * RY]; pts.push(p); if (dec(i) === 2) p10.push(p); }
45	    const rA = ease(t, b.e0.decade, b.e0.decade + 0.8) * (1 - ease(t, MV.m_w20.t0, MV.m_w20.t0 + 0.5));
46	    l30.set(pts); l30.visible = rA > 0.01; l30.material.opacity = rA * (0.75 + 0.25 * pulse(t, b.e5.lower, 1.0));
47	    const hA = rA * Math.max(pulse(t, b.e3.far, 1.6), pulse(t, b.e5.lower, 1.2)); l10.set(p10); l10.visible = hA > 0.01; l10.material.opacity = hA;
48	    renderer.render(scene, cam);
49	    // ---------------- lớp phủ
50	    const log = O.begin(t, cw, cam), ok = cw >= 0.95 ? 1 : 0; log.roi = {};
51	    dip(O, 1 - ease(t, 0, 0.4));
52	    figTag(O, hm);
53	    const sc = (x, y, z = 0) => O.toScreen(x, y, z), [, yF] = sc(X.x0, 0, X.zs), [xL] = sc(X.x0, 0, 0.05), [xR] = sc(X.x1, 0, 0.05), end = MV.m_w20.t0 - 0.05;
54	    const top = (k) => sc(stacks[k].position.x, S.med[k] * U, X.zs);
55	    log.roi['e0.decade'] = [xL, sc(0, 3.6)[1], xR, yF];
56	    // nhãn trên (thập kỷ đang nói) + thẻ trên mỗi chồng điển hình (giữ tới hết)
57	    for (let k = 0; k < 4; k++) {
58	      const [name, rate, usd, cl, cu, , ] = LAB[k], nx = k < 3 ? S.up[k + 1] - 0.1 : end, [x, y] = top(k);
59	      log.roi[['e1.typical', 'e2.y2000s', 'e3.y2010s', 'e6.twenty'][k]] = [x - 70, y - 20, x + 70, yF];
60	      if (k < 3) {
61	        label(O, `${name}: rate near ${rate}`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, tagAt[k], k === 2 ? b.e4.gap - 0.1 : nx), claims: cl });
62	        label(O, `typical stack ${usd}`, 960, 268, { align: 'center', kind: 'number', alpha: ok * show(t, tagAt[k], k === 2 ? b.e4.gap - 0.1 : nx), claims: [cu] });
63	        log.roi[['e1.fifteen', 'e2.fourteen', 'e3.twenty'][k]] = [500, 150, 1420, 290];
64	      }
65	      const ta = ok * show(t, tagAt[k], end), xt = Math.min(x, 1715);   // 2020s: thẻ không chạm mép phải vùng an toàn
66	      label(O, name, xt, y - 74, { align: 'center', kind: 'number', px: 48, alpha: ta, claims: [cl[0]] });
67	      label(O, usd, xt, y - 18, { align: 'center', kind: 'number', px: 48, alpha: ta, claims: [cu] });
68	    }
69	    // S18 "more": vạch nét đứt từ đỉnh chồng 1990s sang chồng 2010s
70	    { const [x0, y0] = top(0), [x2] = top(2), a = ok * show(t, b.e3.more, b.e4.gap - 0.1);
71	      seg2(O, x0 + 55, y0, mix(x0 + 55, x2 + 60, lin(t, b.e3.more, b.e3.more + 0.5)), y0, C.ink, 0.85 * a, 4, [14, 10]);
72	      log.roi['e3.more'] = [x0, y0 - 30, x2 + 70, y0 + 30]; log.roi['e3.far'] = [sc(xc(2) - 1.5, 0)[0], sc(0, 2.0)[1], sc(xc(2) + 1.5, 0)[0], sc(0, 1.0)[1]]; }
73	    // S19: bốn ngoặc khoảng chênh (accent) bên trái mỗi chồng điển hình + thẻ
74	    label(O, `typical gap: ${D('term_long')} minus ${D('term_short')} rate`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, b.e4.gap, S.up[3] - 0.1), claims: ['term_long', 'term_short'] });
75	    log.roi['e4.gap'] = [400, 150, 1520, 230];
76	    for (let k = 0; k < 4; k++) {
77	      const bx = stacks[k].position.x - 0.62, h = S.spd[k] * GS * (1 + 0.06 * Math.sin(12 * (t - b.e7.moved)) * pulse(t, b.e7.moved, 1.4));
78	      const [x, y0] = sc(bx, 0, X.zs), [, y1] = sc(bx, h, X.zs), a = ok * show(t, brAt[k], end);
79	      vbrace(O, x, y1, y0, C.accent, a * (0.8 + 0.2 * pulse(t, b.e5.wider, 1.0)), 6 + 3 * pulse(t, b.e5.wider, 1.0), -14);
80	      label(O, LAB[k][5], x - 18, (y0 + y1) / 2 + 16, { align: 'right', kind: 'number', px: 48, color: '#A9C6FF', alpha: a, claims: [LAB[k][6]] });
81	      if (k === 2) log.roi['e4.seven'] = [x - 300, y1 - 10, x + 20, y0];
82	      if (k === 0) log.roi['e4.four'] = [x - 300, y1 - 10, x + 20, y0];
83	    }
84	    log.roi['e5.lower'] = [xL, sc(0, 3.4)[1], xR, sc(0, 0.8)[1]]; log.roi['e5.wider'] = [xL, sc(0, 3.0, X.zs)[1], xR, yF];
85	    // S20: 2020s; vạch từ đỉnh the stack sang chồng 2020s (gần ngang); nhãn
86	    label(O, `${D('era2020_name')}: typical stack ${D('era2020_median_extra_total')}`, 960, 268, { align: 'center', kind: 'number', alpha: ok * show(t, b.e6.one, end), claims: ['era2020_name', 'era2020_median_extra_total'] });
87	    log.roi['e6.one'] = [500, 215, 1420, 290];
88	    { const [sx, sy] = sc(X.stack + 0.45, G.stack_total * U, 0), [x3] = top(3), a = ok * show(t, b.e6.tessa, end), [tx] = sc(X.stack, 0);
89	      seg2(O, sx, sy, mix(sx, x3 + 60, lin(t, b.e6.tessa, b.e6.tessa + 0.7)), sy, C.ink, 0.85 * a, 4, [14, 10]);
90	      seg2(O, tx, 352, tx, sy - 30, C.ink, 0.8 * a, 3);
91	      label(O, "Tessa's stack · ILLUSTRATIVE", 130, 335, { align: 'left', kind: 'name', alpha: a, char: 'Tessa' });
92	      log.roi['e6.tessa'] = [sx - 120, sy - 30, x3 + 70, sy + 30]; }
93	    // S20.2: dòng góc gạch chân ("history, not a forecast")
94	    { const c = O.ctx; c.save(); c.font = '600 54px Inter'; const w0 = c.measureText('US only · ').width, wAll = c.measureText('US only · history, not a forecast').width; c.restore();
95	      seg2(O, 96 + w0, 1024, 96 + wAll, 1024, C.ink, 0.9 * show(t, b.e7.history, MV.m_w20.t1), 4); log.roi['e7.history'] = [96 + w0 - 6, 960, 96 + wAll + 6, 1030]; }
96	    log.roi['e7.moved'] = [sc(stacks[0].position.x - 0.8, 0)[0], sc(0, 3.0, X.zs)[1], xR, yF];
97	    chrome(O);
98	    st.compose(); log.camMoving = CAM.moving(t); return log;
99	  }
100	  return { canvas: st.out, frame };
101	}
102

