  const nR = S.rates.r30.length, RX0 = X.rates[0], RX1 = X.rates[1], rx = (i) => RX0 + (RX1 - RX0) * i / (nR - 1);
  const l30 = Ribbon({ color: C.accent, z: 0.2, width: 0.07, maxPts: nR }), l15 = Ribbon({ color: '#8DB5FF', z: 0.2, width: 0.05, maxPts: nR });
  scene.add(l30, l15);
