      f.scale.set((BAR_W / FLY_W) * (1 - s) + 0.85 * s, (sliver / BUNDLE_TH) * (1 - s) + 0.92 * s, (BAR_D / FLY_D) * (1 - s) + s); f.visible = true; nf++;
      if (!trail || t0 > trail.t0) trail = { k, p, t0 };
    }
