    const dr = lin(t, b.c0.thirty, b.c0.thirty + 1.0) * (nR - 1), rAl = 1 - ease(t, MV.m_out8.t0, MV.m_out8.t0 + 0.5);
    for (const [L, R] of [[l30, S.rates.r30], [l15, S.rates.r15]]) {
